import {Navigator,PROGRAMS,QUESTIONS,LABELS} from './engine.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7M21 3 10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',community:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',book:'<path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2V3Zm20 0h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7V3Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',leaf:'<path d="M20 3C9 2 2 8 5 15s15 5 15-12ZM4 21l10-12"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6L16 3Z"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`;
const short={bc_resident:'Living in BC',status_category:'Status in Canada',is_post_secondary_student:'Post-secondary student',institution_offers_service:'Institution offers the service',naturalized_citizen:'Naturalized citizen',federal_exception:'Special federal pathway',pr_class:'PR category',pr_landing_date:'PR month'};
let catalog,nav,view='home',editing=null,showChanges=false,toastTimer;
const source=id=>catalog.sources.find(s=>s.id===id);
function readable(field,value){if(!value)return 'Not provided';if(field==='pr_landing_date')return new Date(value+'T12:00:00').toLocaleDateString('en-CA',{month:'long',year:'numeric'});return QUESTIONS[field]?.options?.find(x=>x[0]===value)?.[1]||value;}
function toast(message){const el=document.querySelector('#notice');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function goto(target){view=target;render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main')?.focus({preventScroll:true});}
function header(){return `<header class="header"><a class="brand" href="#home" aria-label="VERA home" data-nav="home"><img src="icon.svg" alt=""><span class="wordmark">VERA</span><span class="brand-divider"></span><small>Your next step in BC</small></a><nav class="nav" aria-label="Main navigation"><button data-nav="${nav.goal?'results':'home'}" class="${['home','questions','results'].includes(view)?'active':''}">Your journey</button><button data-nav="sources" class="${view==='sources'?'active':''}">Sources</button><button data-nav="about" class="${view==='about'?'active':''}">About VERA</button></nav><span class="meta"><span class="dot"></span>Made for newcomers</span></header>`;}
function footer(){return `<footer class="footer"><div>Small steps. A new beginning.<br>VERA is an independent prototype for British Columbia.</div><div class="links"><button data-action="privacy">Privacy & scope</button><button data-nav="about">About & attribution</button><a href="https://github.com/diyagiri/VERA" target="_blank" rel="noopener noreferrer">Project on GitHub ${icon('external')}</a></div></footer>`;}
function steps(active){return `<div class="journey-strip" aria-label="Journey progress">${['Your goal','Your situation','Your next steps'].map((s,i)=>`${i?'<div class="step-line" aria-hidden="true"></div>':''}<div class="step ${i===active?'active':i<active?'complete':''}" ${i===active?'aria-current="step"':''}><i>${i<active?'✓':`0${i+1}`}</i><span>${s}</span></div>`).join('')}</div>`;}
function demoNotice(){return nav.demo?`<div class="notice-box">${icon('info')}<p><strong>Fictional demonstration.</strong> Results illustrate draft rule logic, not approved screening. Your edits remain part of this fictional scenario. <button class="text-button" data-action="reset">Start your own journey</button></p></div>`:'';}
function home(){return `<section class="hero"><div><div class="eyebrow">A little clarity goes a long way</div><h1>A clearer path to<br>your next chapter.</h1><p>Find your way through newcomer support in BC.<br>A few questions. Trusted sources. A plan you can act on.</p></div><div class="hero-aside"><span class="number">You don’t have to<br>figure it all out.</span><p>We’ll help you understand what to ask, where to go, and what to do next.</p></div></section>${steps(0)}<div class="grid-home"><section class="panel goal-panel"><div class="panel-kicker">Let’s start with you</div><h2>What would you like help with?</h2><p class="subtext">Tell us what you’re working toward. Keep personal details out.</p><form id="goal-form"><label class="field-label" for="goal">Your goal</label><textarea id="goal" name="goal" maxlength="600" required placeholder="I’m new to BC and looking for help settling in and paying for school…" aria-describedby="goal-privacy"></textarea><div class="suggestions" aria-label="Suggested goals"><button type="button" class="chip" data-goal="I need newcomer support with settling in, English practice and finding work in BC.">Settle into life in BC</button><button type="button" class="chip" data-goal="I want to understand student funding for my education in BC.">Explore student funding</button><button type="button" class="chip" data-goal="I need newcomer support to help with finding a job in BC.">Find support for work</button></div><button class="primary full" type="submit">Find my next step ${icon('arrow')}</button><p class="privacy-line" id="goal-privacy">${icon('lock')} No account, ID numbers or documents needed.</p><p id="goal-error" class="error" role="alert"></p></form></section><aside class="routes-preview"><div class="routes-title">Three pathways, one place to start</div>${Object.entries(PROGRAMS).map(([pid,p])=>`<div class="route-mini"><span class="icon-box">${icon(p.icon)}</span><div><h3>${p.name}</h3><p>${p.description}</p></div><button class="arrow" data-source="${p.source}" aria-label="Read about ${esc(p.name)}">${icon('external')}</button></div>`).join('')}<div class="demo-block"><div><p>Just exploring?</p><small>Meet Mei, a fictional student in BC.</small></div><button class="text-button" data-demo="mei">Try a demo ${icon('external')}</button></div></aside></div><div class="trust-row"><div class="trust-item">${icon('book')}<div><strong>Grounded in official sources</strong><p>Know where the guidance comes from.</p></div></div><div class="trust-item">${icon('edit')}<div><strong>Your answers, your control</strong><p>Update a detail. Revise your next steps.</p></div></div><div class="trust-item">${icon('shield')}<div><strong>Clear about what’s uncertain</strong><p>Official programs make the final decision.</p></div></div></div>`;}
function answers(){const keys=Object.keys(QUESTIONS).filter(f=>nav.facts[f]&&nav.facts[f]!=='unknown'||nav.skipped.has(f));return `<aside class="panel answers"><h3>Your journey so far</h3><p class="question-goal">${esc(nav.goal)}</p>${keys.length?keys.map(f=>`<div class="answer-row"><div><small>${short[f]}</small>${esc(readable(f,nav.facts[f]))}</div><button data-edit="${f}" aria-label="Edit ${short[f]}">Edit</button></div>`).join(''):'<p class="empty-note">Only relevant questions. Skip anything you’re unsure about — we’ll keep it as an open question.</p>'}<p class="privacy-line">${icon('lock')} Kept only in this open page.</p></aside>`;}
function questions(){const field=nav.next();if(!field){view='results';return results();}const q=QUESTIONS[field];return `<div class="view-head"><div><button class="back" data-nav="home">${icon('back')} Your goal</button><h1>A little about your situation.</h1><p>Your answers help us prepare the right questions and next steps.</p></div></div>${steps(1)}${demoNotice()}<div class="question-layout"><section class="panel question-panel"><div class="panel-kicker">One step at a time</div><h2>${q.title}</h2><p class="subtext">${q.why}</p>${field==='federal_exception'?`<p class="subtext"><a href="${esc(source('S3').url)}" target="_blank" rel="noopener noreferrer">See the official list of pathways ${icon('external')}</a></p>`:''}${q.type==='month'?`<form id="month-form"><label class="field-label" for="pr-month">Month and year</label><input type="month" id="pr-month" class="month-input" min="1900-01" max="${nav.asOf.slice(0,7)}" required><p id="month-error" class="error" role="alert"></p><button class="primary" style="margin-top:18px">Continue ${icon('arrow')}</button></form><button class="text-button" data-answer="" data-field="${field}">Skip this question</button>`:`<div class="options">${q.options.map(([v,label])=>`<button class="option" data-field="${field}" data-answer="${esc(v)}"><span class="radio" aria-hidden="true"></span>${label}</button>`).join('')}</div>`}<div class="question-footer"><span class="mini-note">Not sure? That’s okay.<br>Uncertainty stays visible in your plan.</span><button class="text-button" data-nav="results">See my plan so far →</button></div></section>${answers()}</div>`;}
function cardDescription(r){if(!nav.demo)return 'This pathway needs independent rule review. You can still use the official guidance and prepare questions for a provider.';if(r.state==='needs_information')return `Still to confirm: ${r.missing.map(f=>short[f]?.toLowerCase()||f).join(', ')}.`;if(r.state==='blocker_found')return r.rules.find(x=>x.outcome==='fail')?.reason;if(r.state==='no_blocker_in_checked_criteria')return 'The draft checks found no blocker. Unchecked conditions and provider intake still need confirmation.';return r.rules.find(x=>x.outcome==='review_required')?.reason||'Official review is needed before a reliable screen is possible.';}
function results(){const question=nav.next(),done=nav.plan?.tasks.filter(x=>x.done).length||0;return `<div class="view-head"><div><button class="back" data-action="reset">${icon('back')} Start a new journey</button><h1>Your next chapter starts here.</h1><p>A practical plan, with the open questions kept in view.</p></div><div class="result-actions"><button class="secondary" data-action="answers">${icon('edit')} Review answers</button><button class="primary" data-action="download">${icon('download')} Download plan</button></div></div>${steps(2)}${demoNotice()}${!nav.demo?`<div class="notice-box">${icon('info')}<p><strong>Guidance, with a clear boundary.</strong> The rules in this release are awaiting independent review. VERA can help you prepare; it cannot confirm access or an award.</p></div>`:''}${nav.facts.bc_resident==='no'?`<div class="notice-box">${icon('info')}<p>These pathways focus on British Columbia. Living elsewhere may change your options; use the Benefits Finder and confirm location requirements with the program.</p></div>`:''}${showChanges&&nav.changes.length?`<div class="changes" role="status"><strong>Your plan has been updated · Answer version ${nav.version}</strong>${nav.changes.map(c=>`${PROGRAMS[c.program_id].name}: ${c.before===c.after?'the result stays “'+LABELS[c.after]+'”; its explanation was refreshed':LABELS[c.before]+' → '+LABELS[c.after]}.`).join('<br>')}<br>Your checklist and enquiry were regenerated from your current answers.</div>`:''}${question?`<div class="demo-block"><div><p>There’s still a question you can clarify.</p><small>${esc(QUESTIONS[question].title)}</small></div><button class="text-button" data-nav="questions">Continue →</button></div>`:''}${nav.route.ids.length?`<div class="results-grid">${nav.route.ids.map(pid=>{const r=nav.results[pid],p=PROGRAMS[pid];return `<article class="panel result-card"><div class="result-top"><span class="icon-box">${icon(p.icon)}</span><span class="id">${pid}</span></div><h3>${p.name}</h3><span class="badge ${r.state==='blocker_found'?'block':r.state==='no_blocker_in_checked_criteria'?'pass':r.state==='needs_information'?'gray':'amber'}">${nav.demo?'Draft · ':''}${LABELS[r.state]}</span><p>${esc(cardDescription(r))}</p><button class="source-button" data-result="${pid}">Why this next step ${icon('arrow')}</button></article>`}).join('')}</div>`:''}${nav.route.oos.length?`<div class="panel out-of-scope"><div class="panel-kicker">Beyond VERA’s current scope</div><h3>A good place to keep looking.</h3><p>Your goal includes support outside these three pathways. VERA does not calculate benefits, tax credits or award amounts.</p><a class="secondary" href="${source('S5').url}" target="_blank" rel="noopener noreferrer">Open the Benefits Finder ${icon('external')}</a></div>`:''}<div class="plan-layout"><section class="panel plan-panel"><div class="plan-heading"><div><div class="panel-kicker">Make it manageable</div><h2>Your next steps</h2></div><span class="count" id="task-count">${done}/${nav.plan.tasks.length} complete</span></div><p class="subtext">Tick off tasks as you go. You can edit each step.</p>${nav.plan.tasks.map((t,i)=>`<div class="task ${t.done?'done':''}" id="task-${i}"><input type="checkbox" data-check="${i}" ${t.done?'checked':''} aria-label="Complete step ${i+1}"><div class="task-content"><textarea data-task="${i}" rows="3" aria-label="Edit step ${i+1}" maxlength="1200">${esc(t.text)}</textarea><div class="print-only">${esc(t.text)}</div><a href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">${t.source_id} · Official source ${icon('external')}</a></div></div>`).join('')}<div class="download-row"><button class="secondary" data-action="download">${icon('download')} Download checklist & enquiry</button></div></section><section class="panel plan-panel"><div class="plan-heading"><div><div class="panel-kicker">Find the words</div><h2>Your provider enquiry</h2></div><span class="badge gray">Draft · Not sent</span></div><p class="subtext">Make it your own before contacting a provider.</p><label class="field-label" for="enquiry">Editable message</label><textarea id="enquiry" class="enquiry" maxlength="8000">${esc(nav.plan.enquiry)}</textarea><div class="print-only" id="print-enquiry">${esc(nav.plan.enquiry)}</div><div class="download-row"><button class="secondary" data-action="copy">${icon('copy')} Copy message</button><button class="secondary" data-action="enquiry-download">${icon('download')} Save .txt</button></div><p class="privacy-line">${icon('lock')} Nothing is sent from VERA.</p></section></div><div class="download-row no-print"><button class="text-button" data-action="json">Download source-linked plan data</button><button class="text-button" data-action="print">Print plan</button><span class="mini-note">As of ${nav.asOf} · Answer version ${nav.version}</span></div>${trace()}<p class="subtext">${esc(nav.plan.limits)}</p>`;}
function trace(){return `<details class="trace"><summary>How VERA built this plan · ${nav.events.length} real tool events</summary><p class="mini-note">Guided mode uses deterministic rules. No language model was called. Timings record local operations, not network latency.</p><div class="trace-list">${nav.events.map((e,i)=>`<div class="trace-event"><code>${i+1}. ${e.tool}</code><span>${esc(e.detail)}</span><small>v${e.fact_version} · ${e.duration_ms.toFixed(3)} ms</small></div>`).join('')}</div></details>`;}
function sourcesView(){return `<div class="view-head"><div><div class="eyebrow">Open about the evidence</div><h1>Clarity starts at the source.</h1><p>Five official starting points. Three supported pathways.</p></div><span class="badge amber">0 of 8 rules independently approved</span></div><div class="notice-box">${icon('info')}<p>Source summaries are paraphrases, not official text. Source pages and existing evidence spans were checked on 11 November 2026. ${catalog.sources.every(s=>s.snapshot_verified)?'Byte integrity was verified during this build.':'Full snapshots are absent from this local build; use the recorded official sources and restore exact snapshots before source integrity testing.'} Full snapshots are not redistributed; source inspection is separate from independent rule approval.</p></div><div class="source-grid">${catalog.sources.map(s=>`<article class="panel source-card"><div class="source-top"><span class="badge gray">${s.id} · ${s.program_id||'Discovery only'}</span>${icon('book')}</div><h3>${s.title}</h3><p>${s.publisher}</p><p>${s.summary}</p><div class="source-meta"><span>Registry check<br><strong>${s.checked_on}</strong></span><span>Page modified<br><strong>${s.page_modified_on||'Not displayed'}</strong></span><span>Rule status<br><strong>${s.id==='S5'?'Not a rule source':'Draft · review needed'}</strong></span></div><button class="source-button" data-source="${s.id}">Source details & official link ${icon('arrow')}</button></article>`).join('')}</div>`;}
function about(){return `<div class="view-head"><div><div class="eyebrow">A thoughtful place to start</div><h1>Support without the guesswork.</h1><p>A focused prototype for one newcomer journey, from a goal to a reviewable plan.</p></div></div><div class="about-grid"><section class="panel"><span class="icon-box">${icon('compass')}</span><h3 style="margin-top:21px">From a goal to a next step</h3><p>VERA selects relevant official sources, asks targeted questions, checks a small set of versioned criteria and prepares a checklist and enquiry. Change an answer and the affected checks and draft update.</p><p>The current experience runs a bounded, deterministic tool workflow. No language model is connected. Fictional demos expose draft behavior so the team can review it.</p></section><section class="panel"><span class="icon-box">${icon('shield')}</span><h3 style="margin-top:21px">Useful, and honest about limits</h3><p>Coverage is limited to BC NSP, federal settlement services and StudentAid BC. All eight rule records are drafts. Independent sign-off and verified source snapshots are required before live screening can be enabled.</p><p>VERA does not calculate awards or federal service end dates. An official program or provider confirms conditions and appointment availability.</p></section><section class="panel"><h3>Your session belongs to you</h3><p>Answers stay in this page’s memory. Reloading, closing the page or starting over clears them. No transcripts, analytics, local storage or model requests are used. Downloads are created only when you ask.</p><p>External official links open outside VERA and follow those sites’ policies. Avoid names, ID numbers, addresses or sensitive documents. This public site opens without ChatGPT sign-in.</p></section><section class="panel"><h3>Built on the existing work</h3><p>This application extends <a href="https://github.com/diyagiri/VERA" target="_blank" rel="noopener noreferrer">Diya Giri’s VERA repository</a>, using its Python data contracts, catalog, rules and plan groundwork.</p><p>The inherited thesis/prototype by Kopal Chaudhary is preserved unchanged in <code>baseline/</code>. No employer handbook is included. VERA is not affiliated with or endorsed by these government programs.</p><button class="text-button" data-demo="tomas">Explore Tomas’s uncertainty demo →</button></section></div><section class="panel plan-panel" style="margin-bottom:30px"><div class="panel-kicker">Build verification · 11 November 2026</div><h2>A tested workflow, with review still ahead.</h2><p class="subtext">The original release was checked with Python and browser-engine regression tests. These checks do not establish independent policy validation or user-research results. See the project’s release report for scope and limits.</p><div class="download-row"><a class="secondary" href="https://github.com/diyagiri/VERA" target="_blank" rel="noopener noreferrer">Open project source ${icon('download')}</a></div></section>`;}
function render(){app.innerHTML=`<div class="shell">${header()}<main id="main" tabindex="-1">${view==='home'?home():view==='questions'?questions():view==='results'?results():view==='sources'?sourcesView():about()}</main>${footer()}</div>`;}
function openModal(content){modal.innerHTML=content;modal.showModal();}
function modalHeader(title,kicker='VERA'){return `<div class="modal-head"><div><div class="panel-kicker">${kicker}</div><h2 id="modal-title">${title}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div>`;}
function showSource(id){const s=source(id);openModal(`${modalHeader(s.title,s.id+' · Official source')}<p class="subtext">${s.publisher}</p><div class="source-detail">${s.summary}<br><small>VERA summary · Paraphrased</small></div><dl class="provenance"><dt>Evidence section</dt><dd>${esc(s.evidence_section)}</dd><dt>Registry checked</dt><dd>${s.checked_on}</dd><dt>Page modified</dt><dd>${s.page_modified_on||'Not displayed'}</dd><dt>Policy effective dates</dt><dd>${s.effective_period||'Not established in the registry'}</dd><dt>Web cross-check</dt><dd>${s.web_rechecked_on||'Not rechecked in this build'}${s.web_rechecked_on?' · Does not approve the rule':''}</dd><dt>Source SHA-256</dt><dd><code>${s.sha256}</code></dd><dt>Snapshot integrity</dt><dd>${s.snapshot_verified?'Hash verified at build; full snapshot not bundled':'Snapshot unavailable at build — hash not verified'}</dd><dt>Approval</dt><dd>${id==='S5'?'Discovery only':'RULE_DRAFT · independent review pending'}</dd></dl><a class="primary" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Read official guidance ${icon('external')}</a>`);}
function showResult(pid){const r=nav.results[pid];openModal(`${modalHeader(PROGRAMS[pid].name,pid+' · Explanation')}<span class="badge amber">${nav.demo?'Fictional draft illustration':'Official review required'}</span><p class="subtext" style="margin-top:17px">${nav.demo?'These are illustrative outcomes from draft logic.':'Draft reasons are shown for transparency, not as an eligibility decision.'} No rule in this release has independent approval.</p>${r.rules.map(x=>`<div class="criterion"><code>${x.id} · ${x.source_id} @ ${x.source_version.slice(0,12)}</code><strong>${esc(x.reason)}</strong><br><small>Draft outcome: ${x.outcome.replaceAll('_',' ')} · ${esc(x.gate||'Evidence review needed')}</small></div>`).join('')}<p class="mini-note">Source versions and evidence spans were checked during the build. Full snapshots are not bundled. Unchecked conditions remain for official assessment.</p><button class="secondary" data-source="${PROGRAMS[pid].source}">Open source details ${icon('arrow')}</button>`);}
function editAnswers(field=null){editing=field;const fields=field?[field]:Object.keys(QUESTIONS).filter(f=>nav.facts[f]&&nav.facts[f]!=='unknown'||nav.skipped.has(f)||Object.values(nav.results).some(r=>r.missing.includes(f)));const list=fields.length?fields:['status_category'];openModal(`${modalHeader(field?'Update your answer':'Review your answers','Your details · Session only')}<p class="subtext">Save one changed answer at a time. Changes regenerate the checklist and enquiry; previous edits to those drafts are replaced.</p><form id="edit-form" class="modal-edit">${list.map(f=>`<label>${short[f]}${QUESTIONS[f].type==='month'?`<input name="${f}" type="month" class="month-input" max="${nav.asOf.slice(0,7)}" value="${esc(nav.facts[f]?.slice(0,7)||'')}">`:`<select name="${f}">${QUESTIONS[f].options.map(([v,l])=>`<option value="${v}" ${(nav.facts[f]??'')===v?'selected':''}>${l}</option>`).join('')}</select>`}</label>`).join('')}<p id="edit-error" class="error" role="alert"></p><button class="primary" type="submit">Save changes ${icon('check')}</button></form>`);}
function download(name,text,mime='text/plain'){const blob=new Blob([text],{type:mime+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your download is ready.');}
function startDemo(which){if(which==='tomas')nav.start('I want newcomer settlement help with finding work in BC.',true,{bc_resident:'yes',status_category:'permanent_resident',pr_class:'economic',pr_landing_date:'2021-06-21',is_post_secondary_student:'no'});else nav.start('I just arrived in BC and want help settling in and with student funding.',true,{bc_resident:'yes',status_category:'study_permit',is_post_secondary_student:'yes',institution_offers_service:'unknown',federal_exception:'unknown'});showChanges=false;goto('results');}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;try{
 if(b.hasAttribute('data-close')){modal.close();return;}
 if(b.dataset.source){if(modal.open)modal.close();showSource(b.dataset.source);return;}
 if(b.dataset.result){showResult(b.dataset.result);return;}
 if(b.dataset.nav){event.preventDefault();goto(b.dataset.nav);return;}
 if(b.dataset.demo){startDemo(b.dataset.demo);return;}
 if(b.dataset.goal){const t=document.querySelector('#goal');t.value=b.dataset.goal;t.focus();document.querySelectorAll('[data-goal]').forEach(x=>x.classList.toggle('selected',x===b));return;}
 if(b.hasAttribute('data-answer')){nav.answer(b.dataset.field,b.dataset.answer||null);showChanges=true;goto(nav.next()?'questions':'results');return;}
 if(b.dataset.edit){editAnswers(b.dataset.edit);return;}
 const a=b.dataset.action;
 if(a==='reset'){if(!nav.goal){goto('home');return;}openModal(`${modalHeader('Start a fresh journey?')}<p class="subtext">This clears your answers, checklist and enquiry from this page. Download your plan first if you want to keep it.</p><div class="download-row"><button class="primary" data-action="confirm-reset">Clear and start again</button><button class="secondary" data-close>Keep my journey</button></div>`);}
 if(a==='confirm-reset'){modal.close();nav.reset();showChanges=false;goto('home');toast('Your previous session has been cleared.');}
 if(a==='download'){download('VERA_Plan.md',nav.exportMarkdown(),'text/markdown');}
 if(a==='enquiry-download')download('VERA_Enquiry.txt',nav.plan.enquiry);
 if(a==='json')download('VERA_Plan.json',JSON.stringify({goal:nav.goal,mode:nav.demo?'fictional_draft_demo':'guidance',...nav.plan,results:nav.results,sources:catalog.sources.map(({id,url,sha256,snapshot_verified})=>({id,url,sha256,snapshot_verified}))},null,2),'application/json');
 if(a==='copy'){try{await navigator.clipboard.writeText(nav.plan.enquiry);toast('Enquiry copied. Nothing was sent.');}catch{toast('Clipboard access is unavailable. Use Save .txt or select the message.');}}
 if(a==='print')window.print();
 if(a==='answers')editAnswers();
 if(a==='privacy')openModal(`${modalHeader('Your answers stay with you.','Privacy & scope')}<p class="subtext">VERA keeps answers only in this page’s memory. Reloading, closing the page or starting a new journey clears them. There is no transcript logging, browser storage or model connection in this version.</p><p class="subtext">Downloads contain the information you see and choose to keep. Official links open external websites with their own policies. The three-pathway guidance is limited and all rules await independent review.</p><p class="subtext">Please use categories only. Do not enter names, addresses, SINs, permit numbers or sensitive documents.</p><button class="primary" data-close>Got it</button>`);
 }catch(e){toast(e.message);}});
document.addEventListener('submit',event=>{const f=event.target;event.preventDefault();try{
 if(f.id==='goal-form'){nav.start(new FormData(f).get('goal'));showChanges=false;goto(nav.next()?'questions':'results');}
 if(f.id==='month-form'){const v=document.querySelector('#pr-month').value;nav.answer('pr_landing_date',v?v+'-01':null);showChanges=false;goto(nav.next()?'questions':'results');}
 if(f.id==='edit-form'){const entries=[...new FormData(f).entries()];const changed=entries.filter(([k,v])=>(k==='pr_landing_date'?(v?v+'-01':null):(v||null))!==(nav.facts[k]??null));if(changed.length>1){document.querySelector('#edit-error').textContent='Please save one changed answer at a time so dependent answers can be refreshed.';return;}if(changed.length){let [k,v]=changed[0];nav.answer(k,k==='pr_landing_date'?(v?v+'-01':null):(v||null));showChanges=true;}modal.close();goto('results');}
 }catch(e){const el=f.querySelector('.error');if(el)el.textContent=e.message;else toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.id==='enquiry'){nav.plan.enquiry=e.target.value;document.querySelector('#print-enquiry').textContent=e.target.value;}if(e.target.hasAttribute('data-task')){const i=Number(e.target.dataset.task);nav.plan.tasks[i].text=e.target.value;e.target.nextElementSibling.textContent=e.target.value;}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-check')){const i=Number(e.target.dataset.check);nav.plan.tasks[i].done=e.target.checked;document.querySelector('#task-'+i).classList.toggle('done',e.target.checked);document.querySelector('#task-count').textContent=nav.plan.tasks.filter(x=>x.done).length+'/'+nav.plan.tasks.length+' complete';}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
try{const res=await fetch('./catalog.json');if(!res.ok)throw Error('The source catalog could not be loaded.');catalog=await res.json();nav=new Navigator(catalog);render();}catch(e){app.innerHTML=`<div class="shell"><section class="panel" style="margin-top:60px;padding:30px"><h1>Let’s try again.</h1><p>${esc(e.message)} Reload the page, or use the official <a href="https://www.canada.ca/en/services/benefits/finder.html">Benefits Finder</a>.</p><button class="primary" id="retry">Reload</button></section></div>`;document.querySelector('#retry').onclick=()=>location.reload();}
